// Prompt que le mandas a Claude con cada conversación nueva
const PROMPT_CALIFICADOR = `
Analiza esta conversación de WhatsApp:

CONVERSACIÓN: {{CONVERSACION_TEXTO}}

Aplica el icp_engine.py con pesos: negocio_establecido 30, ya_paga 25, dueño 20, dolor 15, presupuesto 10.

Devuelve SOLO JSON válido:
{
  "score": 0-100,
  "veredicto": "ESCALAR | NUTRIR | RECHAZAR",
  "dolor_principal": "verse barato / perder clientes / competencia mejor",
  "presupuesto_validado": true/false,
  "siguiente_mensaje_sugerido": "Texto de 1 línea para cerrar",
  "es_mi_cliente_ideal": true/false
}

REGLA DE ORO: Si dice "cuánto cuesta" en el primer mensaje sin decir qué vende = RECHAZAR (score <30).
Si dice "tengo [negocio] y [problema visual]" = ESCALAR (score >70).
`;

function decidirEscalado(scoreData, costoConversacionActual) {
  // Esta es la lógica que uso para no perder dinero
  // Si tu cierre es 3 de 10 y cobras $500, tu CPA máximo rentable es $149
  // Yo solo escalo si score >70 Y costo < $45. Si no, lo dejo en nurturing.
  if (scoreData.veredicto === "ESCALAR" && costoConversacionActual <= scoreData.costo_maximo_aceptable) {
    return "METERLE DINERO - Duplicar en ABO $60";
  }
  if (scoreData.veredicto === "NUTRIR") {
    return "NO ESCALAR - Enviar V3 Prueba Social";
  }
  return "APAGAR - No gastar tiempo";
}
